import random
random.seed(42)

with open('/tmp/target_db.txt', 'r') as f:
    target = f.read().strip()

n = len(target)
print(f"Target: {n} nt")

# Parse pairs
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[i] = j
        pairs[j] = i

comp = {'A': 'U', 'U': 'A', 'G': 'C', 'C': 'G'}
bases = ['A', 'C', 'G', 'U']

# Generate 2000 candidates
candidates = []
for trial in range(2000):
    seq = ['A'] * n
    for i in range(n):
        if i in pairs:
            j = pairs[i]
            if i < j:
                r = random.random()
                if r < 0.35:
                    seq[i], seq[j] = 'G', 'C'
                elif r < 0.60:
                    seq[i], seq[j] = 'C', 'G'
                elif r < 0.80:
                    seq[i], seq[j] = 'A', 'U'
                elif r < 0.95:
                    seq[i], seq[j] = 'U', 'A'
                else:
                    seq[i], seq[j] = 'G', 'U'
        else:
            seq[i] = random.choice(['A', 'A', 'U', 'C'])  # bias toward A/U for unpaired

    s = ''.join(seq)
    assert len(s) == n, f"Bad length: {len(s)}"
    candidates.append(s)

# Print in JSON format for batch_fold
import json
print(json.dumps(candidates[:100]))
print(f"\nTotal generated: {len(candidates)}")
